-- ==========================================================================
-- feed_ingredients: aminokwasy, witaminy i rozszerzony sklad
--
-- PLIK GENEROWANY przez scripts/gen-feed-nutrients-sql.py — nie edytuj recznie.
-- Zrodlo wartosci: src/data/feedIngredients.ts, ktory powstaje z arkusza
-- 'Normy zywieniowe.xls' Marka (arkusze Skladniki/Mineralne/Witaminy/Aminokwasy).
--
-- DLACZEGO W BAZIE, A NIE TYLKO W PLIKU: kalkulator czyta skladniki wylacznie
-- z Supabase, gdy sa tam wiersze z source='baza' — a jest ich 124. Plik TS to
-- fallback na pierwsze malowanie i tryb offline.
--
-- PUSTA KOMORKA W ARKUSZU = 0. Tak wprowadzal je Marek: gdy w zrodle nie bylo
-- danych, uznawal, ze skladnika nie ma albo wystepuje w ilosciach sladowych.
-- Sprawdzone przed importem: wszystkie 18 ziaren i straczkowych ma komplet
-- dwunastu aminokwasow, a puste skupiaja sie w dodatkach mineralnych (8 z 8),
-- enzymach i premiksach — czyli tam, gdzie zero jest prawda.
--
-- CEN NIE RUSZAMY — te w arkuszu sa sprzed pietnastu lat.
-- ==========================================================================

ALTER TABLE public.feed_ingredients
  ADD COLUMN IF NOT EXISTS sucha_masa numeric,
  ADD COLUMN IF NOT EXISTS tluszcz numeric,
  ADD COLUMN IF NOT EXISTS popiol numeric,
  ADD COLUMN IF NOT EXISTS skrobia numeric,
  ADD COLUMN IF NOT EXISTS cukier numeric,
  ADD COLUMN IF NOT EXISTS p_przyswajalny numeric,
  ADD COLUMN IF NOT EXISTS cl numeric,
  ADD COLUMN IF NOT EXISTS s numeric,
  ADD COLUMN IF NOT EXISTS cu numeric,
  ADD COLUMN IF NOT EXISTS co numeric,
  ADD COLUMN IF NOT EXISTS lys numeric,
  ADD COLUMN IF NOT EXISTS met numeric,
  ADD COLUMN IF NOT EXISTS met_cys numeric,
  ADD COLUMN IF NOT EXISTS trp numeric,
  ADD COLUMN IF NOT EXISTS thr numeric,
  ADD COLUMN IF NOT EXISTS ile numeric,
  ADD COLUMN IF NOT EXISTS leu numeric,
  ADD COLUMN IF NOT EXISTS val numeric,
  ADD COLUMN IF NOT EXISTS his numeric,
  ADD COLUMN IF NOT EXISTS arg numeric,
  ADD COLUMN IF NOT EXISTS phe numeric,
  ADD COLUMN IF NOT EXISTS tyr numeric,
  ADD COLUMN IF NOT EXISTS wit_a numeric,
  ADD COLUMN IF NOT EXISTS wit_d3 numeric,
  ADD COLUMN IF NOT EXISTS wit_e numeric,
  ADD COLUMN IF NOT EXISTS wit_b1 numeric,
  ADD COLUMN IF NOT EXISTS wit_b2 numeric,
  ADD COLUMN IF NOT EXISTS wit_b6 numeric,
  ADD COLUMN IF NOT EXISTS kwas_pantotenowy numeric,
  ADD COLUMN IF NOT EXISTS kwas_foliowy numeric,
  ADD COLUMN IF NOT EXISTS biotyna numeric,
  ADD COLUMN IF NOT EXISTS niacyna numeric,
  ADD COLUMN IF NOT EXISTS wit_b12 numeric,
  ADD COLUMN IF NOT EXISTS cholina numeric,
  ADD COLUMN IF NOT EXISTS kwas_linolowy numeric;

COMMENT ON COLUMN public.feed_ingredients.lys IS 'Lizyna, % w paszy.';
COMMENT ON COLUMN public.feed_ingredients.met_cys IS 'Metionina + cystyna razem — tak podaja je normy.';
COMMENT ON COLUMN public.feed_ingredients.p_przyswajalny IS 'Fosfor przyswajalny — to on liczy sie w bilansie, nie ogolny.';
COMMENT ON COLUMN public.feed_ingredients.tluszcz IS 'Tluszcz surowy, %. Normy zywieniowe maja na niego wymaganie, ktorego do tej pory nie bylo z czego policzyc.';

-- Naprawa nazwy uszkodzonej przy seedzie (escapowanie wyciekło do wartosci).
UPDATE public.feed_ingredients SET nazwa = 'Premiks 2,5 "PT"' WHERE nazwa = 'Premiks 2,5 \"PT\"';

